  ('eq_ht_at_children_roles_20260524', '9ET0/02', 'Component 2 — Prose', 'Pearson Edexcel', null, 'Compare how the writers present the roles of children in Hard Times and Atonement.', 'childhood', 40, 'Hard Times / Atonement', 'Hard Times', 'Atonement', array['AO1', 'AO2', 'AO3', 'AO4']::text[], 'top_band', 'childhood', array['children as products of adult systems', 'imagination as moral formation and distortion', 'child testimony and adult responsibility', 'narrative control over damaged childhood']::text[], array['qcl_childhood_fact_fancy', 'qcl_briony_order_testimony']::text[], array['stem_childhood_systems_ao1', 'stem_childhood_method_ao2', 'stem_childhood_context_ao3']::text[], array['Retelling Briony''s plot before establishing a comparative argument.', 'Treating Dickens as simply pro-child and McEwan as simply anti-child.', 'Bolting Victorian education context onto the end of the paragraph.']::text[], array['Use ''role'' conceptually: child as victim, witness, author, moral test and social product.', 'Make every paragraph pivot between formation in Hard Times and misformation in Atonement.']::text[], 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false, '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
  ('eq_ht_at_important_choices_20260524', '9ET0/02', 'Component 2 — Prose', 'Pearson Edexcel', null, 'Compare how the writers present characters making important choices in Hard Times and Atonement.', 'important choices', 40, 'Hard Times / Atonement', 'Hard Times', 'Atonement', array['AO1', 'AO2', 'AO3', 'AO4']::text[], 'strong', 'important choices', array['choice under social pressure', 'speech as action', 'choice and later guilt']::text[], array['qcl_louisa_collapse', 'qcl_briony_testimony']::text[], array['stem_choice_pressure_ao1', 'stem_knowledge_guilt_ao4']::text[], array['Listing choices without judging how free they are.']::text[], array['Separate action, agency and consequence within the topic sentence.']::text[], 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false, '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
  ('eq_ht_at_restrictions_20260524', '9ET0/02', 'Component 2 — Prose', 'Pearson Edexcel', null, 'Compare how the writers present restrictions placed on individuals within society.', 'restriction', 40, 'Hard Times / Atonement', 'Hard Times', 'Atonement', array['AO1', 'AO2', 'AO3', 'AO4']::text[], 'top_band', 'restriction', array['class restriction', 'gendered restriction', 'narrative restriction']::text[], array['qcl_coketown_system', 'qcl_robbie_class']::text[], array['stem_restriction_systems_ao4', 'stem_class_social_criticism_ao3']::text[], array['Using society as vague background rather than an active pressure.']::text[], array['Name the institution doing the restricting before moving to evidence.']::text[], 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false, '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
