  ('stem_childhood_systems_ao1', 'Both novels present childhood as {concept}, but Dickens locates the damage in {adult system}, whereas McEwan locates it in {misreading or narrative habit}.', 'comparison', array['AO1', 'AO4']::text[], 'Comparative', 'Comparative', array['childhood']::text[], 'top_band', 'Fill the placeholders, then add one method term before any quotation.', 5010, true, 'top_band', 'childhood', 'roles of children', array['Louisa Gradgrind', 'Tom Gradgrind', 'Sissy Jupe', 'Briony Tallis']::text[], array['Facts', 'girl number twenty', 'world just so']::text[], array['comparative thesis', 'conceptual contrast']::text[], 'Victorian utilitarian formation versus interwar class-coded childhood.', 'Formation in Hard Times; misformation in Atonement.', 'Fill the placeholders, then add one method term before any quotation.', 6, 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false),
  ('stem_childhood_method_ao2', 'Dickens''s use of {method} makes the child seem {effect}, while McEwan''s {method} makes childhood perception feel {effect}; this contrast matters because {judgement}.', 'method_analysis', array['AO2', 'AO4']::text[], 'Comparative', 'Comparative', array['childhood']::text[], 'top_band', 'Write three sentences: method, effect, comparative judgement.', 5020, true, 'top_band', 'childhood', 'method comparison', array['Sissy Jupe', 'Bitzer', 'Briony Tallis']::text[], array['girl number twenty', 'Facts', 'Briony''s testimony anchor']::text[], array['satire', 'capitalisation', 'free indirect discourse', 'restricted focalisation']::text[], 'Link method to educational theory or narrative modernity.', 'External adult pressure versus internal narrative pressure.', 'Write three sentences: method, effect, comparative judgement.', 5, 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false),
  ('stem_childhood_context_ao3', '{Context} is not background here: it explains why {child/character} learns to see {object/person/world} as {mistaken value}.', 'context', array['AO3', 'AO1']::text[], 'Comparative', 'Comparative', array['childhood']::text[], 'strong', 'Make context explain a character''s perception, not just the author''s world.', 5030, true, 'strong', 'childhood', 'context integration', array['Sissy Jupe', 'Louisa Gradgrind', 'Briony Tallis', 'Robbie Turner']::text[], array['Sleary''s people anchor', 'Robbie class anchor']::text[], array['contextual cause', 'interpretive verb']::text[], 'Utilitarian schooling, circus fancy, interwar estate hierarchy.', 'Context should cause a reading choice in both texts.', 'Make context explain a character''s perception, not just the author''s world.', 4, 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false),
  ('stem_choice_pressure_ao1', 'The important choice appears personal, but both writers show it is shaped by {social pressure}: {Hard Times character} is constrained by {pressure}, while {Atonement character} acts through {pressure}.', 'comparison', array['AO1', 'AO4']::text[], 'Comparative', 'Comparative', array['important choices']::text[], 'strong', 'Open with agency, then test how free the choice really is.', 5040, true, 'strong', 'important choices', 'choice and agency', array['Louisa Gradgrind', 'Gradgrind', 'Briony Tallis', 'Cecilia Tallis']::text[], array['Louisa collapse anchor', 'Briony testimony anchor']::text[], array['dialogue', 'structural crisis', 'focalisation']::text[], 'Victorian patriarchy and interwar class credibility.', 'Constrained consent versus confident misrecognition.', 'Open with agency, then test how free the choice really is.', 6, 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false),
  ('stem_restriction_systems_ao4', 'Restriction in both novels is most powerful when it looks normal: Dickens makes {restriction} visible through {image/method}, whereas McEwan makes {restriction} operate through {social assumption/narrative gap}.', 'method_analysis', array['AO2', 'AO4']::text[], 'Comparative', 'Comparative', array['restriction']::text[], 'top_band', 'Use one setting detail and one social detail; compare their pressure.', 5050, true, 'top_band', 'restriction', 'society and individual', array['Stephen Blackpool', 'Louisa Gradgrind', 'Robbie Turner', 'Cecilia Tallis']::text[], array['muddle', 'Coketown smoke', 'Robbie class anchor']::text[], array['industrial imagery', 'dialect', 'free indirect discourse', 'silence']::text[], 'Industrial capitalism and interwar English class hierarchy.', 'Visible machinery versus invisible assumption.', 'Use one setting detail and one social detail; compare their pressure.', 7, 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false),
  ('stem_education_formal_informal_ao2', 'Education is formal in {Hard Times scene} but informal in {Atonement scene}; the methods differ, yet both teach characters to {moral or interpretive outcome}.', 'method_analysis', array['AO1', 'AO2', 'AO4']::text[], 'Comparative', 'Comparative', array['education']::text[], 'top_band', 'Avoid saying ''education is important''; specify what each education teaches.', 5060, true, 'top_band', 'education', 'education', array['Gradgrind', 'Sissy Jupe', 'Briony Tallis', 'Cecilia Tallis']::text[], array['Facts', 'girl number twenty', 'Briony''s play anchor']::text[], array['imperative', 'numbering', 'free indirect discourse']::text[], 'Formal utilitarian schooling versus informal literary/class training.', 'Education as formation of perception.', 'Avoid saying ''education is important''; specify what each education teaches.', 6, 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false),
  ('stem_friendship_trust_ao1', 'Friendship functions less as simple affection than as {moral function}: in Dickens it {supports/rescues/exposes}, while in McEwan it {resists/is destroyed by/reveals} social suspicion.', 'comparison', array['AO1', 'AO4']::text[], 'Comparative', 'Comparative', array['friendship']::text[], 'secure', 'Define friendship before using character evidence.', 5070, true, 'secure', 'friendship', 'relationships', array['Sissy Jupe', 'Louisa Gradgrind', 'Robbie Turner', 'Cecilia Tallis']::text[], array['Sissy care anchor', 'Robbie Cecilia letter anchor']::text[], array['dialogue', 'letter', 'contrast']::text[], 'Victorian domestic sympathy and interwar reputational risk.', 'Friendship as moral attention versus fragile trust.', 'Define friendship before using character evidence.', 5, 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false),
  ('stem_marriage_transaction_ao3', 'Marriage becomes a social technology in both novels: Dickens presents it as {transaction}, while McEwan presents it as {concealment/status repair}, revealing {contextual judgement}.', 'context', array['AO1', 'AO3', 'AO4']::text[], 'Comparative', 'Comparative', array['marriage']::text[], 'strong', 'Name the social function of marriage in the topic sentence.', 5080, true, 'strong', 'marriage', 'marriage', array['Louisa Gradgrind', 'Bounderby', 'Lola Quincey', 'Paul Marshall']::text[], array['Louisa Bounderby proposal anchor', 'Lola Marshall marriage anchor']::text[], array['structural irony', 'social tableau', 'narrative omission']::text[], 'Victorian marital economics and twentieth-century respectability.', 'Marriage as exchange versus marriage as cover story.', 'Name the social function of marriage in the topic sentence.', 6, 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false),
  ('stem_knowledge_guilt_ao4', 'Knowledge arrives too {late/narrowly/confidently}: Dickens shows {character} learning {truth}, but McEwan shows {character} discovering that knowledge cannot undo {harm}.', 'comparison', array['AO1', 'AO4']::text[], 'Comparative', 'Comparative', array['knowledge']::text[], 'top_band', 'Separate knowing, admitting and repairing.', 5090, true, 'top_band', 'knowledge', 'knowledge and guilt', array['Gradgrind', 'Louisa Gradgrind', 'Briony Tallis']::text[], array['Gradgrind late knowledge anchor', 'absolute power']::text[], array['recognition scene', 'metafictional coda', 'retrospection']::text[], 'Victorian reform possibility versus postmodern limits of repair.', 'Late moral knowledge versus irreversible historical harm.', 'Separate knowing, admitting and repairing.', 6, 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false),
  ('stem_memory_reconstruction_ao2', 'Memory is not storage but reconstruction: McEwan''s {method} makes the past feel {effect}, while Dickens''s {method} makes remembered childhood operate as {moral pressure}.', 'method_analysis', array['AO2', 'AO4']::text[], 'Comparative', 'Comparative', array['memory']::text[], 'strong', 'Make form carry the argument about memory.', 5100, true, 'strong', 'memory', 'memory', array['Briony Tallis', 'Louisa Gradgrind', 'Gradgrind']::text[], array['Briony coda anchor', 'Louisa childhood anchor']::text[], array['retrospection', 'metafiction', 'collapse scene']::text[], 'Postwar memory ethics and Victorian moral retrospection.', 'Memory as unstable reconstruction versus moral reckoning.', 'Make form carry the argument about memory.', 7, 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false),
  ('stem_place_system_stage_ao2', 'Setting is not a backdrop: {place} acts as {system/stage}, and the writer''s {method} makes individual behaviour appear {effect}.', 'method_analysis', array['AO2', 'AO1']::text[], 'Comparative', 'Comparative', array['place']::text[], 'strong', 'Use setting to explain behaviour, not just atmosphere.', 5110, true, 'strong', 'place', 'settings', array['Coketown', 'Tallis household', 'Robbie Turner']::text[], array['Coketown smoke', 'Tallis heat anchor', 'Dunkirk road anchor']::text[], array['industrial imagery', 'pathetic fallacy', 'spatial symbolism']::text[], 'Industrial urbanisation, country-house hierarchy and wartime dislocation.', 'Place as social machine versus place as interpretive theatre.', 'Use setting to explain behaviour, not just atmosphere.', 5, 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false),
  ('stem_class_social_criticism_ao3', 'The social criticism is sharpest when class controls {voice/belief/mobility}: Dickens exposes this through {method}, while McEwan exposes it through {method}.', 'method_analysis', array['AO2', 'AO3', 'AO4']::text[], 'Comparative', 'Comparative', array['social criticism']::text[], 'top_band', 'Make class do something active in your sentence.', 5120, true, 'top_band', 'social criticism', 'class', array['Stephen Blackpool', 'Bounderby', 'Robbie Turner', 'Briony Tallis']::text[], array['muddle', 'Robbie class anchor']::text[], array['dialect', 'caricature', 'restricted focalisation']::text[], 'Industrial class hierarchy and interwar class credibility.', 'Class as external oppression versus internalised assumption.', 'Make class do something active in your sentence.', 6, 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false),
  ('stem_independence_agency_ao1', 'Independence is presented as {possible/impossible/qualified} because {character} can choose {action} but cannot escape {structure}.', 'context', array['AO1', 'AO3']::text[], 'Comparative', 'Comparative', array['independence']::text[], 'strong', 'Test the limits of independence rather than praising it vaguely.', 5130, true, 'strong', 'independence', 'agency', array['Louisa Gradgrind', 'Cecilia Tallis', 'Robbie Turner', 'Sissy Jupe']::text[], array['Louisa collapse anchor', 'Cecilia defiance anchor']::text[], array['dialogue', 'character contrast', 'structural constraint']::text[], 'Gender, class and family authority.', 'Private resistance against public structures.', 'Test the limits of independence rather than praising it vaguely.', 5, 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false),
  ('stem_violence_visible_invisible_ao4', 'Violence is {visible/invisible} in different ways: Dickens makes harm systemic through {industrial image}, whereas McEwan makes harm narrative through {misreading or withheld truth}.', 'method_analysis', array['AO2', 'AO4']::text[], 'Comparative', 'Comparative', array['violence']::text[], 'top_band', 'Compare the form of violence before the example.', 5140, true, 'top_band', 'violence', 'violence', array['Stephen Blackpool', 'Robbie Turner', 'Briony Tallis']::text[], array['Coketown smoke', 'Dunkirk body-image anchor', 'testimony anchor']::text[], array['imagery', 'synecdoche', 'delayed revelation']::text[], 'Industrial violence and wartime/social violence.', 'Material damage versus epistemic damage.', 'Compare the form of violence before the example.', 7, 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false),
  ('stem_changing_relationships_ao1', 'The relationship changes when {knowledge/pressure/desire} enters it; Dickens structures this as {movement}, while McEwan structures it as {rupture or retrospective revision}.', 'method_analysis', array['AO1', 'AO2', 'AO4']::text[], 'Comparative', 'Comparative', array['changing relationships']::text[], 'strong', 'Use a before/after structure without retelling the plot.', 5150, true, 'strong', 'changing relationships', 'relationships', array['Louisa and Gradgrind', 'Cecilia and Robbie', 'Briony and Cecilia']::text[], array['Louisa collapse anchor', 'Cecilia Robbie fountain anchor']::text[], array['scene structure', 'retrospection', 'dialogue']::text[], 'Family authority and class/gender pressures.', 'Reformable relationship versus irreparable rupture.', 'Use a before/after structure without retelling the plot.', 6, 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false),
  ('stem_difficult_circumstances_ao3', 'Difficult circumstances reveal not only character but system: {Hard Times example} exposes {Victorian pressure}, while {Atonement example} exposes {twentieth-century pressure}.', 'context', array['AO1', 'AO3', 'AO4']::text[], 'Comparative', 'Comparative', array['difficult circumstances']::text[], 'strong', 'Turn circumstance into cause, then into judgement.', 5160, true, 'strong', 'difficult circumstances', 'suffering', array['Stephen Blackpool', 'Louisa Gradgrind', 'Robbie Turner', 'Cecilia Tallis']::text[], array['muddle', 'factory system anchor', 'Dunkirk road anchor']::text[], array['pathos', 'setting', 'free indirect discourse']::text[], 'Industrial work, gendered family structures, war and class.', 'Systemic hardship in both texts, differently embodied.', 'Turn circumstance into cause, then into judgement.', 6, 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false)
