insert into public.ao_annotations (
  id, essay_id, paragraph_id, annotation_order, text_span, ao_tags,
  explanation, why_it_scores, improvement_note, annotation_type, created_at, updated_at
)
values
  ('ann_child_001', 'essay_children_roles_level5_20260524', 'para_children_roles_1', 1, 'Both Dickens and McEwan make children central to their social criticism, but they give childhood almost opposite dramatic functions.', array['AO1', 'AO4']::text[], 'Opens with a comparative conceptual claim rather than plot.', 'AO1 is controlled and AO4 is immediate.', 'Could name the exact opposition in the same sentence.', 'thesis', '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
  ('ann_child_002', 'essay_children_roles_level5_20260524', 'para_children_roles_1', 2, 'Dickens presents childhood as something adults deform, while McEwan presents childhood as a stage where adult structures, especially class and gender, can be misread and then brutally enforced.', array['AO1', 'AO3', 'AO4']::text[], 'Sets up the essay route and embeds context as an active pressure.', 'It compares both texts and turns class/gender into argument, not background.', 'A concise method pointer could make the thesis even richer.', 'structural link', '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
  ('ann_child_003', 'essay_children_roles_level5_20260524', 'para_children_roles_2', 3, 'Gradgrind''s opening demand for "Facts" turns education into command, and the capitalised abstraction makes fact sound less like knowledge than a false religion.', array['AO2', 'AO3']::text[], 'Analyses diction and typography while linking to utilitarian education.', 'Method is connected to ideological effect.', 'Add a second micro-word if time allows.', 'AO2 method', '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
  ('ann_child_004', 'essay_children_roles_level5_20260524', 'para_children_roles_2', 4, 'Sissy Jupe''s reduction to "girl number twenty" is especially useful because Dickens compresses a whole pedagogy into a label: the child is counted before she is known.', array['AO2', 'AO1']::text[], 'Uses a short quotation for precise method-led analysis.', 'Explains how naming performs depersonalisation.', 'Could link the label to the later contrast with Briony faster.', 'evidence use', '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
  ('ann_child_005', 'essay_children_roles_level5_20260524', 'para_children_roles_2', 5, 'Where Dickens uses caricature and repeated imperatives to show adults pressing children into shape, McEwan uses focalisation to show a child pressing the world into story.', array['AO2', 'AO4']::text[], 'A clean comparative method sentence.', 'The sentence compares form and effect in both texts.', 'Strong enough for Level 5; keep this pattern in later paragraphs.', 'AO4 comparison', '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
  ('ann_child_006', 'essay_children_roles_level5_20260524', 'para_children_roles_3', 6, 'Her circus background matters contextually: Dickens uses Sleary''s world of performance and fancy to resist mid-Victorian utilitarian education, especially the belief that facts alone could produce social improvement.', array['AO3', 'AO2']::text[], 'Context is woven into the reading of Sissy''s function.', 'Avoids bolt-on context because the history explains the character role.', 'Could mention Household Words only if it serves the argument.', 'AO3 context', '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
  ('ann_child_007', 'essay_children_roles_level5_20260524', 'para_children_roles_3', 7, 'Briony''s mistake over Robbie is not only childish confusion; it is a socially authorised misreading.', array['AO1', 'AO3']::text[], 'Conceptual refinement: the argument avoids moral simplification.', 'Shows Level 5 nuance and precise contextual causation.', 'Pair with a verified short quotation in final revision.', 'evaluative comment', '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
  ('ann_child_008', 'essay_children_roles_level5_20260524', 'para_children_roles_4', 8, 'Bitzer reproduces utilitarian calculation, while Briony reproduces class prejudice in the grammar of certainty.', array['AO1', 'AO3', 'AO4']::text[], 'Compact comparison based on social systems and linguistic action.', 'Balances both texts and makes a judgement about causation.', 'Could add an AO2 phrase explaining ''grammar of certainty''.', 'topic sentence', '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
  ('ann_child_009', 'essay_children_roles_level5_20260524', 'para_children_roles_4', 9, 'McEwan makes the reader experience uncertainty through restricted perception and delayed correction, so the child''s statement becomes a narrative event as well as a plot event.', array['AO2', 'AO1']::text[], 'Explains narrative method and its effect on judgement.', 'Method is treated as meaning, not decoration.', 'Excellent sentence to reuse for narrative-authority questions.', 'AO2 method', '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
  ('ann_child_010', 'essay_children_roles_level5_20260524', 'para_children_roles_5', 10, 'The AO4 hinge is that both writers link girlhood to restricted agency, but Dickens emphasises emotional deprivation while McEwan emphasises the dangerous authority of narrative interpretation.', array['AO1', 'AO4']::text[], 'Explicitly names the comparative hinge.', 'Prevents sequential discussion and sharpens conceptual contrast.', 'In the final essay, remove the label ''AO4 hinge'' if it feels too meta.', 'AO4 comparison', '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
  ('ann_child_011', 'essay_children_roles_level5_20260524', 'para_children_roles_6', 11, 'Dickens allows a partial correction: Gradgrind learns too late that his children needed fancy, affection and moral imagination.', array['AO1', 'AO3']::text[], 'Concluding judgement stays precise and acknowledges partial repair.', 'Shows nuance without drifting into a new paragraph.', 'Could add ''reformist'' if contextual vocabulary is needed.', 'conclusion', '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
  ('ann_child_012', 'essay_children_roles_level5_20260524', 'para_children_roles_6', 12, 'Both writers make childhood a moral origin, but only Dickens leaves open the possibility that formation can be repaired.', array['AO1', 'AO4']::text[], 'Final comparative judgement sharpens the thesis.', 'A Level 5 conclusion modifies the opening claim rather than repeats it.', 'Add one form contrast if time remains.', 'conclusion', '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z')
on conflict (id) do update set
  essay_id = excluded.essay_id,
  paragraph_id = excluded.paragraph_id,
  annotation_order = excluded.annotation_order,
  text_span = excluded.text_span,
  ao_tags = excluded.ao_tags,
  explanation = excluded.explanation,
  why_it_scores = excluded.why_it_scores,
  improvement_note = excluded.improvement_note,
  annotation_type = excluded.annotation_type,
  updated_at = now();

