  ('qml_muddle_restriction', 'muddle', 'Stephen Blackpool''s repeated account of social confusion', 'Hard Times', 'Stephen Blackpool', 'repeated demotic noun', 'restriction', 'eq_ht_at_restrictions_20260524', 'stem_class_social_criticism_ao3', 'The simple repeated word conveys structural injustice without elite vocabulary.', 'Robbie''s constrained credibility in Atonement.', 'verified quotation', 'teacher review required', 'ChatGPT session, 24 May 2026', 'annotated essay practice', false, '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
  ('qml_absolute_power', 'absolute power', 'Briony''s late metafictional reflection', 'Atonement', 'Briony Tallis', 'metafictional theological vocabulary', 'knowledge', 'eq_ht_at_knowledge_20260524', 'stem_knowledge_guilt_ao4', 'The phrase exposes the gap between fictional control and real moral repair.', 'Gradgrind''s late but socially limited recognition.', 'quote anchor / paraphrase', 'teacher review required', 'ChatGPT session, 24 May 2026', 'annotated essay practice', false, '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z')
