insert into public.misconception_upgrades (
  id, weakness, diagnosis, example_problem_sentence, improved_level_5_version,
  linked_drill_id, source, content_type, verification_status, reviewed,
  created_at, updated_at
)
values
  ('mis_implied_comparison', 'Comparison is implied but not explicit enough', 'The paragraph discusses both novels but does not name the hinge between them.', 'Dickens shows children are badly educated. McEwan also shows Briony making a mistake.', 'Where Dickens makes childhood damage the product of adult education, McEwan makes childhood error the point at which adult class assumptions become active.', 'stem_childhood_systems_ao1', 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false, '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
  ('mis_bolted_context', 'AO3 is bolted on rather than integrated', 'Context appears as a historical fact after the analysis instead of explaining the character or method.', 'This links to Victorian education, which was strict.', 'Dickens''s strict schoolroom matters because mid-Victorian faith in factual instruction is exactly what turns Sissy from a child into a numbered object.', 'stem_childhood_context_ao3', 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false, '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
  ('mis_method_no_effect', 'AO2 identifies a method but does not explain effect', 'The sentence names a technique but does not say what it makes the reader think.', 'McEwan uses free indirect discourse for Briony.', 'McEwan''s free indirect discourse traps the reader inside Briony''s confident ordering, so the later error feels like a failure of perception rather than a simple lie.', 'stem_childhood_method_ao2', 'ChatGPT session, 24 May 2026', 'annotated essay practice', 'teacher review required', false, '2026-05-24T00:00:00.000Z', '2026-05-24T00:00:00.000Z'),
